mapper.insert:
/* 영수증 등록 */
INSERT INTO RECPT
     ( MBR_SN
     , ATCH_FILE_SN
     , OCR_PRCS_STTS_CD
     , OCR_DMND_SRC_CD
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{mbrSn}
     , #{atchFileSn}
     , #{ocrPrcsSttsCd}
     , #{ocrDmndSrcCd}
     , NOW()
     , NOW() )

mapper.update:
/* 영수증 처리 상태 변경(이전 상태 조건) */
UPDATE RECPT
   SET OCR_PRCS_STTS_CD = #{aftrSttsCd}
     , MDFCN_DT = NOW()
 WHERE RECPT_SN = #{recptSn}
   AND OCR_PRCS_STTS_CD IN

        #{bfrSttsCd}

/* 영수증 분석 결과 저장과 상태 변경 */
UPDATE RECPT
   SET OCR_PRCS_STTS_CD = #{aftrSttsCd}
     , OCR_RSPNS_JSON = #{ocrRspnsJson}
     , MDFCN_DT = NOW()
 WHERE RECPT_SN = #{recptSn}
   AND OCR_PRCS_STTS_CD = #{bfrSttsCd}

/* 영수증 저장 완료 처리(멱등 요청 ID·저장일시 기록) */
UPDATE RECPT
   SET OCR_PRCS_STTS_CD = #{aftrSttsCd}
     , IDMPT_DMND_ID = #{idmptDmndId}
     , STRG_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE RECPT_SN = #{recptSn}
   AND OCR_PRCS_STTS_CD IN

        #{bfrSttsCd}

mapper.insert:
/* 영수증 상태 변경 이력 등록 */
INSERT INTO RECPT_STTS_HSTRY
     ( RECPT_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{recptSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

mapper.select:
/* 마지막 상태 이력의 변경 사유 */
SELECT CHG_RSN
  FROM RECPT_STTS_HSTRY
 WHERE RECPT_SN = #{recptSn}
 ORDER BY RECPT_STTS_HSTRY_SN DESC
 LIMIT 1

/* 관리자 OCR 현황 목록(기간·출처·상태, 최신순, OCR 응답 미조회) */ SELECT R.RECPT_SN , R.MBR_SN , M.MBR_NCNM , R.OCR_DMND_SRC_CD , R.OCR_PRCS_STTS_CD , R.REG_DT FROM RECPT R JOIN MBR M ON M.MBR_SN = R.MBR_SN
AND R.OCR_PRCS_STTS_CD = #{cond.ocrPrcsSttsCd}
ORDER BY R.REG_DT DESC , R.RECPT_SN DESC

/* 관리자 원본 보기용 첨부파일 번호(회원 소유 검사 없음) */
SELECT ATCH_FILE_SN
  FROM RECPT
 WHERE RECPT_SN = #{recptSn}
